import{_ as o,o as t,c as a,ae as s}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"Operational assets","description":"","frontmatter":{"id":"2078011537","title":"Operational assets","state":"Approved","created":"2026-10-07T00:00:00.000Z","tags":["directory","devops","docker","compose","helm"],"category":"Platform"},"headers":[],"relativePath":"adrs/2078011537/README.md","filePath":"adrs/2078011537/README.md"}'),n={name:"adrs/2078011537/README.md"};function r(i,e,c,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="operational-assets" tabindex="-1">Operational assets <a class="header-anchor" href="#operational-assets" aria-label="Permalink to &quot;Operational assets&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../9316364013/README.html">ADR#9316364013</a> reserves <code>devops/</code> for operational assets. This ADR fixes the layout for the assets that reach nothing live: container images, the local stack and Helm charts. Anything that creates, changes or reconciles a live account or cluster is covered by <a href="./../6561361204/README.html">ADR#6561361204</a>.</p><p>A survey of our repositories found compose files at the repository root as <code>docker-compose.yml</code>, Dockerfiles next to the code they build, and Helm charts under <code>deploy/</code>, <code>charts/</code> or <code>devops/helm/</code>. The repositories that had settled this converged on <code>devops/</code> split by tool, with the Docker tree split again by what a file is for: an image directory holds build input that lands in the artifact, a compose service directory holds run-time input mounted over it.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> place every operational asset that reaches nothing live under <code>devops/&lt;tool&gt;/</code>, named after the tool that consumes it (<code>docker/</code>, <code>helm/</code>, <code>terragrunt/</code>).</li><li>You <strong>MUST NOT</strong> keep <code>docker-compose.yml</code>, <code>compose.yaml</code>, a <code>Dockerfile</code> for a shipped image, or a chart anywhere else, including the repository root and <code>deploy/</code>.</li><li>You <strong>MUST</strong> drive the stack through mise tasks (<code>compose:up</code>, <code>compose:down</code>, <code>images:build</code>), never through scripts inside <code>devops/</code>.</li></ul><h3 id="container-images" tabindex="-1">Container images <a class="header-anchor" href="#container-images" aria-label="Permalink to &quot;Container images&quot;">​</a></h3><ul><li>You <strong>MUST</strong> give every image that ships its own directory <code>devops/docker/images/&lt;name&gt;/</code>, where <code>&lt;name&gt;</code> is the deployable it produces and matches the command or chart that uses it.</li><li>You <strong>MUST</strong> keep only build input beside the <code>Dockerfile</code>: files the build copies in and nothing else reads. Source that a language workspace owns stays in that workspace; the image reaches it through the build context, it does not copy it in.</li><li>You <strong>MUST</strong> use the image directory as the build context unless the <code>Dockerfile</code> needs source from the repository. An image that does <strong>MUST</strong> take it through <code>RUN --mount=type=bind,source=&lt;path&gt;</code> with <code>&lt;path&gt;</code> written from the repository root, and <strong>MUST</strong> then use the repository root as the context. The build task <strong>MUST</strong> derive the context from that mount, so no list of images has to be kept.</li><li>You <strong>MUST</strong> keep ignore rules beside the <code>Dockerfile</code> as <code>Dockerfile.dockerignore</code>, and <strong>MUST NOT</strong> keep a <code>.dockerignore</code> at the repository root.</li></ul><h3 id="compose" tabindex="-1">Compose <a class="header-anchor" href="#compose" aria-label="Permalink to &quot;Compose&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> keep one <code>compose.yaml</code> per environment. A repository with a single local stack places it directly under <code>devops/docker/compose/</code>; one with several environments places each under <code>devops/docker/compose/&lt;environment&gt;/</code>.</p></li><li><p>You <strong>MUST</strong> place what a compose service reads at run time under <code>services/&lt;service&gt;/</code> next to the <code>compose.yaml</code> that mounts it, named by the compose service name. A <code>Dockerfile</code> <strong>MAY</strong> live there only for an image that never ships.</p></li><li><p>You <strong>MUST</strong> build a shipped image from <code>devops/docker/images/&lt;name&gt;/</code>, and nothing under <code>images/</code> or <code>helm/</code> <strong>MUST</strong> read anything under <code>compose/</code>.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── &lt;workspace&gt;/                # source a root-context image bind-mounts</span></span>
<span class="line"><span>└── devops/docker</span></span>
<span class="line"><span>    ├── images</span></span>
<span class="line"><span>    │   ├── &lt;self-contained&gt;</span></span>
<span class="line"><span>    │   │   ├── Dockerfile</span></span>
<span class="line"><span>    │   │   ├── Dockerfile.dockerignore</span></span>
<span class="line"><span>    │   │   └── &lt;input&gt;/        # copied by this Dockerfile only</span></span>
<span class="line"><span>    │   └── &lt;from-source&gt;</span></span>
<span class="line"><span>    │       ├── Dockerfile      # RUN --mount=type=bind,source=&lt;workspace&gt;/...</span></span>
<span class="line"><span>    │       └── Dockerfile.dockerignore</span></span>
<span class="line"><span>    └── compose</span></span>
<span class="line"><span>        ├── compose.yaml            # single stack</span></span>
<span class="line"><span>        ├── services/&lt;service&gt;/     # run-time mounts</span></span>
<span class="line"><span>        └── &lt;environment&gt;           # only when there is more than one stack</span></span>
<span class="line"><span>            ├── compose.yaml</span></span>
<span class="line"><span>            └── services/&lt;service&gt;/</span></span></code></pre></div></li></ul><h3 id="helm" tabindex="-1">Helm <a class="header-anchor" href="#helm" aria-label="Permalink to &quot;Helm&quot;">​</a></h3><ul><li>You <strong>MUST</strong> place each chart under <code>devops/helm/charts/&lt;chart&gt;/</code>, named after the deployable it installs.</li><li>You <strong>MUST</strong> keep defaults in <code>values.yaml</code> and treat every other values file as a case that overrides it, named after the case: an environment, a feature combination, an authentication mode.</li><li>You <strong>MUST</strong> name a deployment case <code>values.&lt;case&gt;.yaml</code> beside <code>values.yaml</code>.</li><li>You <strong>MUST</strong> name a chart-testing case <code>ci/&lt;case&gt;-values.yaml</code>. That is the only pattern chart-testing discovers, and a case under any other name is silently skipped, so CI passes without ever rendering it.</li><li>You <strong>MUST NOT</strong> keep a case anywhere else in the chart, or under a name that does not say which case it is.</li><li>You <strong>MUST</strong> compose several charts through an umbrella chart with <code>file://</code> dependencies in the same directory, never by reaching into another chart&#39;s templates.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../9316364013/README.html">ADR#9316364013</a>: Reserved repository directories</li><li><a href="./../6561361204/README.html">ADR#6561361204</a>: Live infrastructure</li><li><a href="https://docs.docker.com/reference/compose-file/" target="_blank" rel="noreferrer">Compose file reference</a></li><li><a href="https://helm.sh/docs/topics/charts/#the-chart-file-structure" target="_blank" rel="noreferrer">Helm chart file structure</a></li><li><a href="https://github.com/helm/chart-testing/blob/main/doc/ct_lint.md" target="_blank" rel="noreferrer">chart-testing lint</a></li></ul>`,14)])])}const u=o(n,[["render",r]]);export{m as __pageData,u as default};
